code.cpp:
class Solution {
public:
    vector<vector<int>> closestNodes(TreeNode* root, vector<int>& queries) {
        vector<int> vals;
        inorder(root, vals);
        vector<vector<int>> ans;
        int n = vals.size();
        for (int q : queries) {
            int i = lower_bound(vals.begin(), vals.end(), q) - vals.begin();
            int mx = (i < n) ? vals[i] : -1;
            int mn;
            if (i < n && vals[i] == q) {
                mn = vals[i];
            } else if (i > 0) {
                mn = vals[i - 1];
            } else {
                mn = -1;
            }
            ans.push_back({mn, mx});
        }
        return ans;
    }
private:
    void inorder(TreeNode* node, vector<int>& vals) {
        if (!node) return;
        inorder(node->left, vals);
        vals.push_back(node->val);
        inorder(node->right, vals);
    }
};
